CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ============================================================================
-- 0. CLEAN DROP OF ANY PREVIOUS SCHEMA TABLES TO PREVENT COLUMN MISMATCHES
-- ============================================================================
DROP TABLE IF EXISTS public.order_status_history CASCADE;
DROP TABLE IF EXISTS public.order_items CASCADE;
DROP TABLE IF EXISTS public.cart_items CASCADE;
DROP TABLE IF EXISTS public.carts CASCADE;
DROP TABLE IF EXISTS public.delivery_rules CASCADE;
DROP TABLE IF EXISTS public.enquiry_attachments CASCADE;
DROP TABLE IF EXISTS public.product_variants CASCADE;
DROP TABLE IF EXISTS public.product_images CASCADE;
DROP TABLE IF EXISTS public.addresses CASCADE;
DROP TABLE IF EXISTS public.store_sections CASCADE;

DROP TABLE IF EXISTS public.quotations CASCADE;
DROP TABLE IF EXISTS public.enquiries CASCADE;
DROP TABLE IF EXISTS public.orders CASCADE;
DROP TABLE IF EXISTS public.customers CASCADE;
DROP TABLE IF EXISTS public.banners CASCADE;
DROP TABLE IF EXISTS public.products CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;
DROP TABLE IF EXISTS public.site_settings CASCADE;

-- 1. site_settings
CREATE TABLE IF NOT EXISTS public.site_settings (
  id TEXT PRIMARY KEY,
  announcement_text TEXT,
  announcement_badge TEXT,
  announcement_enabled BOOLEAN DEFAULT TRUE,
  featured_product_slug TEXT,
  promo_price_paise BIGINT,
  promo_countdown_end TIMESTAMPTZ,
  promo_countdown_hours INTEGER DEFAULT 4,
  whatsapp_number TEXT,
  support_phone TEXT,
  support_email TEXT,
  meta_pixel_id TEXT,
  footer_tagline TEXT,
  address_line TEXT,
  hero_bg_image TEXT,
  hero_mobile_image TEXT,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. categories
CREATE TABLE IF NOT EXISTS public.categories (
  id TEXT PRIMARY KEY,
  store_section TEXT NOT NULL DEFAULT 'EVERYDAY',
  parent_id TEXT,
  name TEXT NOT NULL,
  slug TEXT UNIQUE NOT NULL,
  description TEXT,
  image_url TEXT,
  banner_url TEXT,
  display_order INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT TRUE,
  subcategories JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. products
CREATE TABLE IF NOT EXISTS public.products (
  id TEXT PRIMARY KEY,
  store_section TEXT NOT NULL DEFAULT 'EVERYDAY',
  category_id TEXT,
  category_slug TEXT,
  category_name TEXT,
  subcategory_name TEXT,
  name TEXT NOT NULL,
  slug TEXT UNIQUE NOT NULL,
  sku TEXT,
  short_description TEXT,
  description TEXT,
  selling_price_paise BIGINT NOT NULL,
  original_price_paise BIGINT,
  launch_price_label TEXT,
  features JSONB DEFAULT '[]'::jsonb,
  specifications JSONB DEFAULT '[]'::jsonb,
  dimensions JSONB DEFAULT '{}'::jsonb,
  material TEXT,
  delivery_info TEXT,
  stock_quantity INTEGER DEFAULT 0,
  availability_status TEXT DEFAULT 'IN_STOCK',
  is_featured BOOLEAN DEFAULT FALSE,
  is_trending BOOLEAN DEFAULT FALSE,
  is_bestseller BOOLEAN DEFAULT FALSE,
  is_demo_data BOOLEAN DEFAULT FALSE,
  is_active BOOLEAN DEFAULT TRUE,
  request_quote_only BOOLEAN DEFAULT FALSE,
  images JSONB DEFAULT '[]'::jsonb,
  variants JSONB DEFAULT '[]'::jsonb,
  reviews JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. banners
CREATE TABLE IF NOT EXISTS public.banners (
  id TEXT PRIMARY KEY,
  placement TEXT NOT NULL,
  store_section TEXT NOT NULL DEFAULT 'EVERYDAY',
  product_id TEXT,
  product_slug TEXT,
  title TEXT NOT NULL,
  subtitle TEXT,
  badge_text TEXT,
  price_paise BIGINT,
  launch_price_label TEXT,
  cta_primary_text TEXT,
  cta_primary_link TEXT,
  cta_secondary_text TEXT,
  cta_secondary_link TEXT,
  image_url TEXT NOT NULL,
  mobile_image_url TEXT,
  display_order INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. customers
CREATE TABLE IF NOT EXISTS public.customers (
  id TEXT PRIMARY KEY,
  full_name TEXT NOT NULL,
  phone TEXT NOT NULL,
  email TEXT,
  district TEXT,
  city TEXT,
  full_address TEXT,
  pincode TEXT,
  total_orders INTEGER DEFAULT 0,
  total_enquiries INTEGER DEFAULT 0,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. orders
CREATE TABLE IF NOT EXISTS public.orders (
  id TEXT PRIMARY KEY,
  order_number TEXT UNIQUE NOT NULL,
  customer_id TEXT,
  customer_name TEXT NOT NULL,
  customer_phone TEXT NOT NULL,
  customer_email TEXT,
  district TEXT,
  city_town TEXT,
  full_address TEXT,
  pincode TEXT,
  delivery_instructions TEXT,
  status TEXT NOT NULL DEFAULT 'PENDING',
  subtotal_paise BIGINT NOT NULL,
  delivery_charge_paise BIGINT,
  confirmed_payable_paise BIGINT,
  total_paise BIGINT NOT NULL,
  payment_method TEXT DEFAULT 'ORDER_REQUEST',
  payment_status TEXT DEFAULT 'UNPAID',
  internal_notes TEXT,
  is_purchase_tracked BOOLEAN DEFAULT FALSE,
  items JSONB DEFAULT '[]'::jsonb,
  status_history JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 7. enquiries
CREATE TABLE IF NOT EXISTS public.enquiries (
  id TEXT PRIMARY KEY,
  enquiry_number TEXT UNIQUE NOT NULL,
  customer_id TEXT,
  customer_name TEXT NOT NULL,
  mobile_number TEXT NOT NULL,
  email TEXT,
  store_section TEXT NOT NULL DEFAULT 'PREMIUM',
  enquiry_category TEXT,
  product_reference TEXT,
  requirement_description TEXT,
  preferred_dimensions TEXT,
  material_finish TEXT,
  budget_range TEXT,
  project_location TEXT,
  status TEXT NOT NULL DEFAULT 'NEW',
  assigned_staff TEXT,
  internal_notes TEXT,
  follow_up_history JSONB DEFAULT '[]'::jsonb,
  attachments JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 8. quotations
CREATE TABLE IF NOT EXISTS public.quotations (
  id TEXT PRIMARY KEY,
  quotation_number TEXT UNIQUE NOT NULL,
  enquiry_id TEXT,
  enquiry_number TEXT,
  customer_name TEXT,
  customer_phone TEXT,
  store_section TEXT DEFAULT 'PREMIUM',
  title TEXT,
  quoted_amount_paise BIGINT,
  valid_until TIMESTAMPTZ,
  document_url TEXT,
  summary_notes TEXT,
  status TEXT DEFAULT 'DRAFT',
  created_by TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 9. PERMISSIONS AND GRANTS
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated, service_role;

-- Disable RLS so publishable key and anon key can read/write directly from Next.js server/client
ALTER TABLE public.site_settings DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.products DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.banners DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.customers DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.enquiries DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.quotations DISABLE ROW LEVEL SECURITY;

